/* 收藏切换按钮样式 */
.favorites-toggle {
  margin-top: 8px;
}
.favorites-toggle button {
  padding: 5px 16px;
  border: 1.5px solid #E8C9C9;
  border-radius: 20px;
  background: #fff;
  color: #8B2E2E;
  font-size: 0.85rem;
  cursor: pointer;
  transition: all 0.2s;
}
.favorites-toggle button.active {
  background: #8B2E2E;
  color: #fff;
}

